import { check } from "../shared/check.mjs";

/**
 * `./$types` is generated by SvelteKit beside the route that uses it, and a
 * route's own `+page`/`+layout` siblings are named by position rather than by
 * path. Neither has an alias to be spelled through.
 */
const isFrameworkPath = (specifier) =>
  /^\.{1,2}\/\$types(\.js)?$/.test(specifier) || /^\.\/\+[a-z]/.test(specifier);

/**
 * The vendored tree spells its own imports, and the CLI rewrites them on every
 * regeneration. `vendor-keeps-its-own-spelling` is what governs them.
 */
const isVendored = (tree, path) => tree.within(tree.path("components", "vendor"), path);

export default check({
  name: "no-relative-imports",
  says: "Every cross-file import is spelled through an alias — which is what makes every import check decidable from the specifier alone.",
  run(tree) {
    const found = [];
    for (const path of tree.files) {
      if (!/\.(ts|js|svelte)$/.test(path)) continue;
      if (path.endsWith(".d.ts")) continue;
      if (isVendored(tree, path)) continue;
      const inRoutes = tree.within(tree.routes, path);

      for (const record of tree.imports(path)) {
        if (!record.specifier.startsWith(".")) continue;
        if (inRoutes && isFrameworkPath(record.specifier)) continue;
        found.push({
          path,
          line: record.line,
          message: `relative import "${record.specifier}"`
        });
      }
    }
    return found;
  }
});
